from PIL import Image
import numpy as np
from sklearn.cluster import KMeans
im=np.array(Image.open('first_frame.png').convert('RGB'))
# kmeans colors, subsample
X=im.reshape(-1,3)
k=KMeans(12,random_state=0,n_init=5).fit(X[::4])
labels=k.predict(X).reshape(144,256)
cent=k.cluster_centers_
order=np.argsort(cent.mean(1)); mp={v:i for i,v in enumerate(order)}
chars='0123456789AB'
print([(chars[mp[i]],np.round(cent[i]).astype(int).tolist(),int((labels==i).sum())) for i in order])
# majority at 4x4
for y in range(0,144,4):
 row=''
 for x in range(0,256,4):
  a=labels[y:y+4,x:x+4].ravel(); lab=np.bincount(a,minlength=12).argmax(); row+=chars[mp[lab]]
 print(row)
PY"

